def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether insertions, deletions and replacements can turn s into t
    using at most k operations.

    Keep the furthest source position reachable on each alignment diagonal at
    each edit budget, extending every state through its following equal run.
    This uses O(k) auxiliary space and O((len(s) + len(t)) * k) time.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True
    if k >= max(n, m):
        return True

    start = 0
    while start < n and start < m and s[start] == t[start]:
        start += 1
    # A diagonal d represents source_position - target_position.
    previous = {0: start}
    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(-edits, edits + 1):
            best = -1

            # Replace the next source character with the next target one.
            pos = previous.get(diagonal, -1)
            if pos >= 0 and pos < n and pos - diagonal < m:
                best = pos + 1

            # Delete a source character, increasing the diagonal by one.
            pos = previous.get(diagonal - 1, -1)
            if pos >= 0 and pos < n:
                best = max(best, pos + 1)

            # Insert a target character, decreasing the diagonal by one.
            pos = previous.get(diagonal + 1, -1)
            if pos >= 0 and pos - (diagonal + 1) < m:
                best = max(best, pos)

            if best < 0:
                continue
            target_pos = best - diagonal
            while best < n and target_pos < m and s[best] == t[target_pos]:
                best += 1
                target_pos += 1
            if best == n and target_pos == m:
                return True
            current[diagonal] = best
        previous = current
    return False

from functools import lru_cache


@lru_cache(maxsize=None)
def _count_suffix(remaining: int, digit_sum: int, digit_product: int) -> int:
    """Count beautiful completions; sum zero means no digit has started."""
    if remaining == 0:
        return int(digit_sum > 0 and digit_product % digit_sum == 0)
    if digit_product == 0:
        # A real zero digit makes every completion beautiful.
        return 10 ** remaining

    total = 0
    for digit in range(10):
        if digit_sum == 0 and digit == 0:
            total += _count_suffix(remaining - 1, 0, 1)
        else:
            total += _count_suffix(
                remaining - 1, digit_sum + digit, digit_product * digit
            )
    return total


def _count_up_to(bound: int) -> int:
    if bound <= 0:
        return 0

    digits = [int(digit) for digit in str(bound)]
    total = 0
    digit_sum = 0
    digit_product = 1
    for index, upper in enumerate(digits):
        remaining = len(digits) - index - 1
        for digit in range(upper):
            if digit_sum == 0 and digit == 0:
                total += _count_suffix(remaining, 0, 1)
            else:
                total += _count_suffix(
                    remaining, digit_sum + digit, digit_product * digit
                )
        if digit_sum != 0 or upper != 0:
            digit_sum += upper
            digit_product *= upper

    return total + int(digit_sum > 0 and digit_product % digit_sum == 0)


def count_beautiful_numbers(l: int, r: int) -> int:
    """Count beautiful positive integers in the inclusive range [l, r].

    A number is beautiful when the product of its digits is divisible
    by their sum. The bounds satisfy 1 <= l <= r < 10**9.

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

